import os
import shutil
from typing import List, Dict, Any
from app.core.config import settings
from app.types.results import Result

class ArtifactManager:
    """Centralizes management of file system directory paths and artifacts generated by the AI processing pipeline."""
    @staticmethod
    def get_video_dir(video_id: str) -> str:
        return os.path.abspath(os.path.join(settings.storage.upload_dir, video_id))

    @classmethod
    def create_paths(cls, video_id: str) -> Result[Dict[str, str]]:
        """Initializes standard artifact subfolders for a given video ID."""
        video_dir = cls.get_video_dir(video_id)
        categories = ["original", "frames", "thumbnails", "audio", "ocr", "metadata", "analysis"]
        paths = {}
        try:
            for cat in categories:
                cat_dir = os.path.join(video_dir, cat)
                os.makedirs(cat_dir, exist_ok=True)
                paths[cat] = cat_dir
            return Result.Success(paths)
        except Exception as e:
            return Result.Failure(f"Failed to create artifact directories: {str(e)}")

    @classmethod
    def get_artifact_path(cls, video_id: str, category: str, filename: str) -> str:
        """Resolves the absolute filepath for a given artifact file."""
        return os.path.join(cls.get_video_dir(video_id), category, filename)

    @classmethod
    def save_artifact(cls, video_id: str, category: str, filename: str, content: bytes) -> Result[str]:
        """Saves binary content to the designated category folder."""
        try:
            cls.create_paths(video_id)
            filepath = cls.get_artifact_path(video_id, category, filename)
            with open(filepath, "wb") as f:
                f.write(content)
            return Result.Success(filepath)
        except Exception as e:
            return Result.Failure(f"Failed to save artifact '{filename}': {str(e)}")

    @classmethod
    def list_artifacts(cls, video_id: str, category: str) -> Result[List[str]]:
        """Returns filenames stored in a specific category directory."""
        cls.create_paths(video_id)
        category_dir = os.path.join(cls.get_video_dir(video_id), category)
        try:
            files = os.listdir(category_dir)
            # Filter directories
            files = [f for f in files if os.path.isfile(os.path.join(category_dir, f))]
            return Result.Success(files)
        except Exception as e:
            return Result.Failure(f"Failed to list artifacts in '{category}': {str(e)}")

    @classmethod
    def cleanup(cls, video_id: str) -> Result[None]:
        """Deletes all files and folders associated with the video ID."""
        video_dir = cls.get_video_dir(video_id)
        try:
            if os.path.exists(video_dir):
                shutil.rmtree(video_dir)
            return Result.Success(None)
        except Exception as e:
            return Result.Failure(f"Failed to cleanup artifact directory: {str(e)}")
